# --------------------------------------------------
# Cluster flux bootstrap repository
# --------------------------------------------------

variable "cluster_name" {
  type = string
}

variable "repository_name" {
  type = string
}

variable "branch" {
  type    = string
  default = "main"
}

variable "github_owner" {
  type = string
}

variable "overwrite_on_create" {
  type        = bool
  default     = true
  description = "Enable overwriting existing files"
}

variable "prune" {
  type        = bool
  default     = true
  description = "Enable Garbage collection"
}

# --------------------------------------------------
# Shared manifests repository
# --------------------------------------------------

variable "shared_repo_url" {
  type        = string
  description = "The https url for the shared manifests Git repository"
}

variable "shared_repo_branch" {
  type        = string
  default     = "main"
  description = "The default branch for the shared manifests Git repository"
}

variable "overlay_folder" {
  type        = string
  description = "The kustomize overlay folder in the shared manifests repository to reconcile"
}

# --------------------------------------------------
# Git credentials
# --------------------------------------------------

variable "account_id" {
  type        = string
  description = "AWS account id that hosts the shared manifests Git credentials in SSM"
}

variable "iam_role_name" {
  type        = string
  description = "The name of the IAM role the ServiceAccount is annotated with to read the Git credentials from SSM"
}

variable "aws_region" {
  type        = string
  default     = "eu-west-1"
  description = "The AWS region that hosts the shared manifests Git credentials in SSM"
}

# --------------------------------------------------
# Flux bootstrap repository data
# --------------------------------------------------

data "github_repository" "main" {
  full_name = "${var.github_owner}/${var.repository_name}"
}

data "github_branch" "flux_branch" {
  repository = var.repository_name
  branch     = var.branch
}

# --------------------------------------------------
# Local variables
# --------------------------------------------------

locals {
  cluster_target_path = "clusters/${var.cluster_name}"
  ssm_param_owner     = "/eks/${var.cluster_name}/shared-manifests/git-owner"
  ssm_param_token     = "/eks/${var.cluster_name}/shared-manifests/git-token"
}

terraform {
  required_version = ">= 1.3.0, < 1.6.0"

  required_providers {
    github = {
      source  = "integrations/github"
      version = "~> 6.2.0"
    }
  }
}

terraform {
  required_version = ">= 1.8.0"

  required_providers {
    github = {
      source  = "integrations/github"
      version = "~> 6.2.0"
    }
  }
}

