---
apiVersion: node.eks.aws/v1alpha1
kind: NodeConfig
spec:
    cluster:
        name: ${cluster_name}
        apiServerEndpoint: ${eks_endpoint}
        certificateAuthority: ${eks_certificate_authority}
        cidr: ${cidr}
    kubelet:
        config:
%{ if vpc_cni_prefix_delegation_enabled }
            maxPods: ${max_pods}
%{ endif ~}
            registryPullQPS: 0
%{ if cpu != null || memory != null }
            kubeReserved:
%{ endif ~}
%{ if cpu != null }
                cpu: ${cpu}
%{ endif ~}
%{ if memory != null }
                memory: ${memory}
%{ endif ~}

